arguments.command:
curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" --data-urlencode "types=public_channel,private_channel" --data-urlencode "exclude_archived=false" --data-urlencode "limit=1000" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERROR', d); sys.exit()
for c in d['channels']:
    n=c.get('name','')
    if 'release' in n.lower() or 'deploy' in n.lower():
        print(json.dumps({'id':c['id'],'name':n,'created':c['created'],'is_private':c.get('is_private',False),'members':c.get('num_members'),'topic':(c.get('topic') or {}).get('text','')[:80]}))
"

